from dataclasses import dataclass

@dataclass
class Politica:
    limite_intentos: int = 3
    espera_ms: int = 120

def ejecutar(tarea, politica):
    for intento in range(politica.limite_intentos):
        resultado = tarea.ejecutar()
        if resultado.correcto:
            return resultado
        tarea.esperar(politica.espera_ms * (intento + 1))
    raise RuntimeError("la tarea no terminó")
